-function benutzer_array(int $limit = 100): array
+function benutzer_array(int $limit = 100, ?string $suche = null, ?string $status = null): array
 {
     $db = datenbank_verbindung();
     if (!$db) {
         return [];
     }

-    $abfrage = $db->prepare('SELECT * FROM benutzer ORDER BY aktiv DESC, gesperrt ASC, id DESC LIMIT :limit');
+    $sql = 'SELECT * FROM benutzer';
+    $parameter = [];
+
+    // Statusfilter hinzufügen
+    if ($status !== null && in_array($status, ['alle', 'aktiv', 'inaktiv', 'gesperrt'], true)) {
+        switch ($status) {
+            case 'aktiv':
+                $sql .= ' WHERE aktiv = 1 AND gesperrt = 0';
+                break;
+            case 'inaktiv':
+                $sql .= ' WHERE aktiv = 0';
+                break;
+            case 'gesperrt':
+                $sql .= ' WHERE gesperrt = 1';
+                break;
+            default: // 'alle'
+                // Keine zusätzliche Bedingung
+                break;
+        }
+    }
+
+    // Suchfilter hinzufügen
+    if ($suche !== null && $suche !== '') {
+        $suche = trim($suche);
+        if (strlen($suche) > 0) {
+            $suche_sql = ' WHERE (benutzername LIKE :suche OR anzeigename LIKE :suche OR email LIKE :suche OR vorname LIKE :suche OR nachname LIKE :suche)';
+
+            // Wenn kein Statusfilter gesetzt ist, füge den Suchfilter hinzu
+            if ($status === null || $status === 'alle') {
+                $sql .= $suche_sql;
+            } else {
+                // Wenn bereits ein Statusfilter existiert, füge den Suchfilter mit AND hinzu
+                $sql .= ' AND (benutzername LIKE :suche OR anzeigename LIKE :suche OR email LIKE :suche OR vorname LIKE :suche OR nachname LIKE :suche)';
+            }
+
+            $parameter[':suche'] = '%' . $suche . '%';
+        }
+    }
+
+    $sql .= ' ORDER BY aktiv DESC, gesperrt ASC, id DESC LIMIT :limit';
+    $abfrage = $db->prepare($sql);
+
+    // Parameter binden
+    foreach ($parameter as $key => $value) {
+        $abfrage->bindValue($key, $value);
+    }
+
     $abfrage->bindValue(':limit', max(1, min($limit, 500)), PDO::PARAM_INT);
     $abfrage->execute();
     return $abfrage->fetchAll() ?: [];
